    internal static IEnumerable<(string Name,Action Run)> All() {
        yield return("rc4 known Witcher DX12 path is evidence-backed while other games stay ambiguous",KnownExe);
        yield return("rc4 confirmed EXE preference survives restart and rejects stale or outside paths",Preferences);
        yield return("rc4 helpers are excluded without losing explicit Show All or path labels",Helpers);
        yield return("rc4 Steam 730 placeholder uses Valve name and unknown IDs keep fallback",SteamNames);
        yield return("rc4 compact generation Details preserves pending edits warnings and exact INI bytes",Compact);
        yield return("rc4 semantic version ordering handles stable prerelease build and UI cultures",Versions);
        yield return("rc4 GitHub parsing ignores drafts prereleases source ZIPs and wrong architectures",Parsing);
        yield return("rc4 update metadata refuses repository URL and asset path substitutions",UnsafeMetadata);
        yield return("rc4 digestless metadata is visible but cannot download",MissingDigest);
        yield return("rc4 update checks cache successful results and recover after rate limits",CacheAndFailures);
        yield return("rc4 download starts at real browser asset endpoint and validates official CDN bytes",Download);
        yield return("rc4 wrong update digest or size leaves no partial file and preserves completed files",BadIntegrity);
        yield return("rc4 corrupt ZIP and ZIP without application EXE are refused despite matching hash",CorruptZip);
        yield return("rc4 cancelled interrupted and failed update downloads preserve prior files",Cancellation);
        yield return("rc4 update redirects reject HTTP credentials foreign hosts ports and lookalikes",Redirects);
        yield return("rc4 stale release metadata blocks a direct download call",Stale);
        yield return("rc4 update WPF states download only and never open files or URLs automatically",Ui);
        yield return("rc4 update and generation UI resources retain six-language integrity",Localization);
    }
    private static void Check(bool value,string reason){if(!value)throw new Exception(reason);}
    private static void Reject(Action action){try{action();}catch(Exception ex)when(ex is IOException or InvalidDataException or HttpRequestException or OperationCanceledException){return;}throw new Exception("Expected operation refusal");}
    private static string Temp(){var p=Path.Combine(Path.GetTempPath(),"RenoDX-RC4",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(p);return p;}
    private static string Create(string root,string relative){var path=Path.Combine(root,relative.Replace('/',Path.DirectorySeparatorChar));Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllText(path,"own synthetic file; never executed");return path;}
    private static void KnownExe(){var root=Temp();var dx11=Create(root,"bin/x64/witcher3.exe");var dx12=Create(root,"bin/x64_dx12/witcher3.exe");var custom=Create(root,"custom.exe");Check(GameExecutableSelection.Automatic(root,"292030",[dx11,dx12,custom],null)==dx12,"Known DX12 not selected");Check(GameExecutableSelection.Automatic(root,"unknown",[dx11,dx12],null) is null,"Heuristics authorized unknown game");Check(GameExecutableSelection.Automatic(root,"unknown",[custom],null)==custom,"Single candidate lost");Check(GameExecutableSelection.Automatic(root,"292030",[dx11,dx12],dx11)==dx11,"Confirmed DX11 lost to DX12");}
    private static void Preferences(){var root=Temp();var path=Path.Combine(root,"private","preferences.json");var prefs=new ApplicationPreferences(path);Check(!prefs.CheckUpdatesAtLaunch,"Network enabled without opt-in");var first=Create(root,"main.exe");var other=Create(root,"second.exe");prefs.ConfirmExe(root,first);prefs.SetUpdateCheck(true);var reload=new ApplicationPreferences(path);Check(reload.CheckUpdatesAtLaunch&&reload.ConfirmedExe(root)==first,"Preferences not persisted");Check(GameExecutableSelection.Automatic(root,"unknown",[first,other],reload.ConfirmedExe(root))==first,"Confirmed candidate lost");File.Delete(first);Check(GameExecutableSelection.Automatic(root,"unknown",[first,other],first)==other,"Stale preference accepted");var outside=Create(Temp(),"other.exe");Check(GameExecutableSelection.Automatic(root,"unknown",[other],outside)==other,"Outside preference accepted");reload.SetUpdateCheck(false);Check(!new ApplicationPreferences(path).CheckUpdatesAtLaunch,"Cannot disable checks");File.WriteAllText(path,"{broken");Check(!new ApplicationPreferences(path).CheckUpdatesAtLaunch,"Corrupt preferences enable networking");}
    private static void Helpers(){var root=Temp();foreach(var file in new[]{"REDprelauncher.exe","WitcherScriptMerger.exe","7za.exe","crashreporter.exe","main.exe"})Create(root,file);var normal=ExecutableCandidatePolicy.Discover(root);Check(normal.Count==1&&Path.GetFileName(normal[0])=="main.exe","Helpers leaked");Check(ExecutableCandidatePolicy.Discover(root,true).Count==5,"Show All lost explicit choices");var choice=new ExecutableChoice(normal[0]);Check(choice.FileName=="main.exe"&&choice.DirectoryPath==root,"RC2 presentation changed");}
    private static void SteamNames(){Check(GameExecutableSelection.DisplayName("730","appid_730")=="Counter-Strike 2"&&GameExecutableSelection.DisplayName("730",null)=="Counter-Strike 2","CS2 fallback wrong");Check(GameExecutableSelection.DisplayName("999",null)=="appid_999"&&GameExecutableSelection.DisplayName("999","Verified local title")=="Verified local title","Other metadata changed");}
    private const BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
    private static IEnumerable<DependencyObject> Tree(DependencyObject root){foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>()){yield return child;foreach(var d in Tree(child))yield return d;}}
    private static void Compact()=>WpfCheckHost.Run(()=>{using var f=new Rc1SettingsChecks.Fixture();var hashes=f.Hashes();StackPanel Panel()=>(StackPanel)f.Window.FindName("GenerationModePanel");Expander Details()=>Tree((Border)Panel().Children[1]).OfType<Expander>().Single();Check(!Details().IsExpanded,"Not compact by default");f.Edit("Enabled","0");Details().IsExpanded=true;typeof(MainWindow).GetMethod("SelectGenerationMethod",Flags)!.Invoke(f.Window,["XMX"]);Check(Details().IsExpanded&&f.Value("Enabled")=="0"&&f.Value("XmxGenerator")=="1","Expansion or edits lost");Details().IsExpanded=false;Check(((TextBlock)Panel().Children[2]).Visibility==Visibility.Visible,"Compact hid XMX warning");foreach(var c in new[]{MfgSettingsCategory.Advanced,MfgSettingsCategory.Other,MfgSettingsCategory.General})f.Select(c);Check(!Details().IsExpanded&&f.Value("Enabled")=="0","Category navigation changed state");Check(hashes.All(p=>f.Hashes()[p.Key]==p.Value),"Expanding wrote configuration");Check(Tree((Border)Panel().Children[1]).OfType<TextBlock>().Any(t=>t.Text.Contains("[Backend] Selected")),"Exact INI removed");});
    private static void Versions(){foreach(var culture in UiLocalization.Cultures){var before=System.Globalization.CultureInfo.CurrentCulture;try{System.Globalization.CultureInfo.CurrentCulture=System.Globalization.CultureInfo.GetCultureInfo(culture);var ordered=new[]{"1.0.0-alpha","1.0.0-alpha.1","1.0.0-alpha.beta","1.0.0-beta","1.0.0-beta.2","1.0.0-beta.11","1.0.0-rc.1","1.0.0","1.1.0","1.2.0-rc.4","1.2.0","1.10.0"};for(var i=1;i<ordered.Length;i++)Check(ApplicationVersion.Parse(ordered[i])!.CompareTo(ApplicationVersion.Parse(ordered[i-1]))>0,"SemVer ordering "+culture);Check(ApplicationVersion.Parse("v1.2.0+build.12")!.CompareTo(ApplicationVersion.Parse("1.2.0"))==0,"Metadata affected precedence");foreach(var bad in new[]{"1.2","1.02.0","1.2.0-01","1.2.0-","../1.2.0","1.2.0/other","1.2.0.0"})Check(ApplicationVersion.Parse(bad) is null,"Invalid SemVer accepted "+bad);}finally{System.Globalization.CultureInfo.CurrentCulture=before;}}}
    private sealed class Fixture:IDisposable {
        internal readonly string Root=Temp();internal readonly byte[] Bytes;internal string Json;internal readonly HttpClient Http;internal readonly ApplicationUpdateService Service;internal readonly List<string> Requests=[];
        internal Func<HttpRequestMessage,HttpResponseMessage>? Reply;
        internal Fixture(byte[]? bytes=null){Bytes=bytes??Zip();Json=Metadata(Bytes);Http=new HttpClient(new Handler(request=>{Requests.Add(request.RequestUri!.AbsoluteUri);return Reply?.Invoke(request)??(request.RequestUri.Host=="api.github.com"?Response(Json):new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(Bytes)});}));Service=new(Http);}
        internal ApplicationRelease Release=>ApplicationUpdateService.Parse(Json).Single();
        internal string Download(IProgress<StreamlineDownloadProgress>? progress=null,CancellationToken token=default)=>Service.DownloadAsync(Release,Root,progress,token).GetAwaiter().GetResult();
        public void Dispose(){Service.Dispose();Http.Dispose();}
    }
    private sealed class Handler(Func<HttpRequestMessage,HttpResponseMessage> reply):HttpMessageHandler {protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){token.ThrowIfCancellationRequested();return Task.FromResult(reply(request));}}
    private static HttpResponseMessage Response(string json)=>new(HttpStatusCode.OK){Content=new StringContent(json)};
    private static byte[] Zip(bool exe=true){using var data=new MemoryStream();using(var zip=new ZipArchive(data,ZipArchiveMode.Create,true)){using var writer=new StreamWriter(zip.CreateEntry(exe?"RenoDX MFG Unlocker.exe":"README.md").Open());writer.Write("own inert test data; not a runnable vendor or application binary");}return data.ToArray();}
    private static string Metadata(byte[] bytes,string tag="v1.3.0",string? digest="auto") {
        var name="RenoDX_MFG_Unlocker_v"+tag.TrimStart('v')+"_Windows_x64.zip";
        return JsonSerializer.Serialize(new[]{new{id=7,url=ApplicationUpdateService.ApiRoot+"/releases/7",html_url=ApplicationUpdateService.WebRoot+"/releases/tag/"+tag,tag_name=tag,name="Application "+tag,body="# Actual release notes\n- Test",published_at="2026-11-01T12:00:00Z",draft=false,prerelease=false,assets=new[]{new{id=9,url=ApplicationUpdateService.ApiRoot+"/releases/assets/9",name,state="uploaded",size=bytes.Length,digest=digest=="auto"?"sha256:"+Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant():digest,browser_download_url=ApplicationUpdateService.WebRoot+"/releases/download/"+tag+"/"+name}}}});
    }
    private static JsonArray Nodes(string json)=>JsonNode.Parse(json)!.AsArray();
    private static void Parsing(){using var f=new Fixture();var nodes=Nodes(f.Json);var draft=nodes[0]!.DeepClone();draft["draft"]=true;nodes.Add(draft);var pre=Nodes(Metadata(f.Bytes,"v9.0.0-rc.1"))[0]!.DeepClone();nodes.Add(pre);var flagged=Nodes(Metadata(f.Bytes,"v10.0.0"))[0]!.DeepClone();flagged["prerelease"]=true;nodes.Add(flagged);var asset=nodes[0]!["assets"]!.AsArray()[0]!.DeepClone();asset["name"]="Source code.zip";asset["browser_download_url"]="https://malicious.invalid/source.zip";nodes[0]!["assets"]!.AsArray().Add(asset);Check(ApplicationUpdateService.Parse(nodes.ToJsonString()).Count==1,"Ineligible releases entered catalog");Check(ApplicationUpdateService.Evaluate("1.2.0-rc.4",f.Release).UpdateAvailable,"New stable not detected");Check(!ApplicationUpdateService.Evaluate("1.3.0",f.Release).UpdateAvailable&&!ApplicationUpdateService.Evaluate("2.0.0-rc.1",f.Release).UpdateAvailable,"Downgrade offered");var missing=Nodes(f.Json);missing[0]!["assets"]!.AsArray()[0]!["name"]="Source code.zip";Check(ApplicationUpdateService.Parse(missing.ToJsonString()).Single().DownloadUrl is null,"Source ZIP selected");}
    private static void UnsafeMetadata(){using var f=new Fixture();foreach(var property in new[]{"html_url","url","browser_download_url","asset-url"}){var nodes=Nodes(f.Json);if(property=="browser_download_url")nodes[0]!["assets"]!.AsArray()[0]![property]="https://github.com/attacker/RenoDX-MFG-Unlocker/releases/download/v1.3.0/package.zip";else if(property=="asset-url")nodes[0]!["assets"]!.AsArray()[0]!["url"]="https://api.github.com/repos/attacker/repo/releases/assets/9";else nodes[0]![property]="https://github.com/attacker/repo";Reject(()=>ApplicationUpdateService.Parse(nodes.ToJsonString()));}var duplicate=Nodes(f.Json);var assets=duplicate[0]!["assets"]!.AsArray();assets.Add(assets[0]!.DeepClone());Reject(()=>ApplicationUpdateService.Parse(duplicate.ToJsonString()));}
    private static void MissingDigest(){using var f=new Fixture();f.Json=Metadata(f.Bytes,digest:null);Check(f.Release.Sha256 is null,"Digest invented");Reject(()=>f.Download());Check(f.Requests.All(r=>r.StartsWith(ApplicationUpdateService.ApiRoot))&&!Directory.GetFiles(f.Root).Any(),"Digestless ZIP fetched");}
    private static void CacheAndFailures(){using var f=new Fixture();var first=f.Service.CheckAsync("1.2.0-rc.4").GetAwaiter().GetResult();Check(first.UpdateAvailable,"First check");f.Service.CheckAsync("1.3.0").GetAwaiter().GetResult();Check(f.Requests.Count==1,"TTL cache unused");f.Reply=_=>new(HttpStatusCode.Forbidden);Reject(()=>f.Service.CheckAsync("1.2.0",true).GetAwaiter().GetResult());f.Reply=_=>throw new HttpRequestException("offline");Reject(()=>f.Service.CheckAsync("1.2.0",true).GetAwaiter().GetResult());f.Reply=null;Check(f.Service.CheckAsync("1.2.0",true).GetAwaiter().GetResult().UpdateAvailable,"Retry failed");}
    private static void Download(){using var f=new Fixture();f.Reply=request=>{Check(request.Headers.Authorization is null,"GitHub token used");if(request.RequestUri!.Host=="api.github.com")return Response(f.Json);if(request.RequestUri.Host=="github.com")return new(HttpStatusCode.Redirect){Headers={Location=new Uri("https://release-assets.githubusercontent.com/github-production-release-asset/12/34?sig=fixture")}};return new(HttpStatusCode.OK){Content=new ByteArrayContent(f.Bytes)};};var file=f.Download();Check(File.ReadAllBytes(file).SequenceEqual(f.Bytes),"Bytes changed");Check(f.Requests.Contains(f.Release.DownloadUrl!)&&f.Requests.Any(r=>r.StartsWith("https://release-assets.githubusercontent.com/")),"Real asset endpoint skipped");var before=f.Requests.Count(r=>r.StartsWith("https://github.com/"));Check(f.Download()==file&&f.Requests.Count(r=>r.StartsWith("https://github.com/"))==before,"Verified cached file redownloaded");Check(Directory.GetFiles(f.Root).Length==1&&!Directory.GetDirectories(f.Root).Any(),"Archive executed/extracted");}
    private static void BadIntegrity(){using var f=new Fixture();var prior=Create(f.Root,"completed.zip");var priorBytes=File.ReadAllBytes(prior);var nodes=Nodes(f.Json);nodes[0]!["assets"]!.AsArray()[0]!["digest"]="sha256:"+new string('0',64);f.Json=nodes.ToJsonString();Reject(()=>f.Download());Check(Directory.GetFiles(f.Root).Length==1&&File.ReadAllBytes(prior).SequenceEqual(priorBytes),"Failed digest damaged completed file");f.Json=Metadata(f.Bytes);f.Reply=r=>r.RequestUri!.Host=="api.github.com"?Response(f.Json):new(HttpStatusCode.OK){Content=new ByteArrayContent([1,2,3])};Reject(()=>f.Download());Check(!Directory.GetFiles(f.Root,"*.partial").Any(),"Size failure left partial data");}
    private static void CorruptZip(){foreach(var bytes in new[]{Encoding.UTF8.GetBytes("broken ZIP"),Zip(false)}){using var f=new Fixture(bytes);Reject(()=>f.Download());Check(!Directory.GetFiles(f.Root).Any(),"Invalid ZIP retained");}}
    private sealed class ImmediateProgress(Action<StreamlineDownloadProgress> action):IProgress<StreamlineDownloadProgress>{public void Report(StreamlineDownloadProgress value)=>action(value);}
    private static void Cancellation(){using var f=new Fixture();var prior=Create(f.Root,"keep.txt");using var cancel=new CancellationTokenSource();Reject(()=>f.Download(new ImmediateProgress(_=>cancel.Cancel()),cancel.Token));Check(File.Exists(prior)&&Directory.GetFiles(f.Root).Length==1,"Cancellation damaged previous file");using var before=new CancellationTokenSource();before.Cancel();Reject(()=>f.Download(token:before.Token));f.Reply=r=>r.RequestUri!.Host=="api.github.com"?Response(f.Json):new(HttpStatusCode.ServiceUnavailable);Reject(()=>f.Download());f.Reply=r=>r.RequestUri!.Host=="api.github.com"?Response(f.Json):new(HttpStatusCode.OK){Content=new StreamContent(new BrokenStream()){Headers={ContentLength=f.Bytes.Length}}};Reject(()=>f.Download());f.Reply=null;Check(File.Exists(f.Download()),"Retry after cancellation/failure failed");}
    private sealed class BrokenStream:MemoryStream {public override ValueTask<int> ReadAsync(Memory<byte> buffer,CancellationToken token=default)=>throw new IOException("synthetic interrupted stream");}
    private static void Redirects(){foreach(var bad in new[]{"http://release-assets.githubusercontent.com/github-production-release-asset/1","https://release-assets.githubusercontent.com.evil.invalid/github-production-release-asset/1","https://user@release-assets.githubusercontent.com/github-production-release-asset/1","https://release-assets.githubusercontent.com:444/github-production-release-asset/1","https://github.com/attacker/file","https://release-assets.githubusercontent.com/not-a-release/1","https://release-assets.githubusercontent.com/github-production-release-asset/1#bad"}){using var f=new Fixture();f.Reply=r=>r.RequestUri!.Host=="api.github.com"?Response(f.Json):new(HttpStatusCode.Redirect){Headers={Location=new Uri(bad)}};Reject(()=>f.Download());Check(f.Requests.Count==2&&!Directory.GetFiles(f.Root).Any(),"Untrusted redirect followed");}}
    private static void Stale(){using var f=new Fixture();var old=f.Release;f.Json=Metadata(f.Bytes,"v1.4.0");Reject(()=>f.Service.DownloadAsync(old,f.Root).GetAwaiter().GetResult());Check(f.Requests.Count==1&&!Directory.GetFiles(f.Root).Any(),"Stale asset downloaded");}
    private static void Pump(Task task){var clock=System.Diagnostics.Stopwatch.StartNew();while(!task.IsCompleted&&clock.Elapsed<TimeSpan.FromSeconds(12)){Dispatcher.CurrentDispatcher.Invoke(()=>{},DispatcherPriority.Background);Thread.Sleep(1);}Check(task.IsCompleted,"Async WPF check timed out");task.GetAwaiter().GetResult();}
    private static void Ui()=>WpfCheckHost.Run(()=>{using var f=new Fixture();var callbacks=0;using var view=new ApplicationUpdateView(f.Service,"1.2.0-rc.4",f.Root,_=>callbacks++,_=>callbacks++);Check(f.Requests.Count==0&&!view.DownloadButton.IsEnabled,"Construction did network work");Pump(view.CheckAsync());Check(view.DownloadButton.IsEnabled&&view.ReleaseButton.IsEnabled&&view.Notes.Text.Contains("Actual release notes"),"Check UI incomplete");Pump(view.DownloadAsync());Check(view.FolderButton.IsEnabled&&!view.Busy&&callbacks==0&&view.Status.Text.Contains("Nothing was installed or executed"),"Automatic action or incorrect completion");view.FolderButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(callbacks==1,"Explicit folder action unavailable");});
    private static void Localization()=>WpfCheckHost.Run(()=>{var l=LocalizedPresentation.Language;using var f=new Fixture();using var view=new ApplicationUpdateView(f.Service,"1.2.0-rc.4",f.Root,_=>{},_=>{});try{Check(l.ValidateCatalogs().Count==0,"Catalog integrity");foreach(var c in UiLocalization.Cultures){l.SetCulture(c,false);foreach(var key in new[]{"Application updates","Check for stable updates at launch","Check for Updates","Download Update","Current application version: {0}",ApplicationUpdateService.IntegrityNotice,"Update ZIP verified and saved. Nothing was installed or executed. Close this app before updating manually."})Check(l.GetCatalog(c).ContainsKey(key)&&(c=="en-US"||l.Lookup(key)!=key),"New untranslated resource "+c+" / "+key);Check((string)view.CheckButton.Content==l.Lookup("Check for Updates")&&view.VersionText.Text.Contains("1.2.0-rc.4"),"Live language changed technical version or did not refresh");}}finally{l.SetCulture("en-US",false);}});
